 // PriceCache serves prices by SKU and by category. Both maps are filled once, at startup.
 type PriceCache struct {
 	mu         sync.Mutex
 	store      Store
 	bySKU      map[string]Price
 	byCategory map[string]map[string]Price
 }

 func (c *PriceCache) Get(sku string) (Price, error) {
 	c.mu.Lock()
 	defer c.mu.Unlock()
 	if p, ok := c.bySKU[sku]; ok {
 		return p, nil
 	}
 	p, err := c.store.Load(sku)
 	if err != nil {
 		return Price{}, err
 	}
 	c.bySKU[sku] = p
 	return p, nil
 }

 func (c *PriceCache) ForCategory(cat string) map[string]Price {
 	c.mu.Lock()
 	defer c.mu.Unlock()
 	return c.byCategory[cat]
 }

+// Invalidate drops a SKU after its price changes, so the next read loads the new price.
+func (c *PriceCache) Invalidate(sku string) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	delete(c.bySKU, sku)
+}
